import json
from fractions import Fraction as Q

# Sparse exact polynomials in x,t.
def add(*polys):
    out = {}
    for p in polys:
        for monomial, coefficient in p.items():
            out[monomial] = out.get(monomial, Q(0)) + coefficient
    return {m: c for m, c in out.items() if c}

def scale(p, k):
    return {m: c * k for m, c in p.items() if c * k}

def mul(p, q):
    out = {}
    for (i, j), a in p.items():
        for (k, l), b in q.items():
            m = (i + k, j + l)
            out[m] = out.get(m, Q(0)) + a * b
    return {m: c for m, c in out.items() if c}

def square(p):
    return mul(p, p)

def main():
    one = {(0, 0): Q(1)}
    x = {(1, 0): Q(1)}
    t = {(0, 1): Q(1)}
    t2 = square(t)

    # x=a/c>0, y=b/c>0, t=sqrt(1+y)>1.
    # Original expression: 1/x + x/t^2 + t^2 - 1.
    boundary = Q(1) + Q(1) / (Q(1) + Q(0)) + Q(0)

    # Verify the exact identity after multiplying by positive x*t^2:
    # F-boundary = (x-t)^2/(x*t^2) + (t-1)^2*(t+2)/t.
    lhs = add(
        t2,
        square(x),
        mul(x, square(t2)),
        scale(mul(x, t2), -(Q(1) + boundary)),
    )
    rhs = add(
        square(add(x, scale(t, -1))),
        mul(mul(x, t),
            mul(square(add(t, scale(one, -1))),
                add(t, scale(one, 2)))),
    )
    identity_verified = lhs == rhs

    # On the admissible path a=c, F=boundary+y^2/(1+y).
    # Compute its derivative numerator exactly:
    # (2y)(1+y)-y^2 = y^2+2y.
    y = t
    path_numerator = square(y)
    path_denominator = add(one, y)
    derivative_numerator = add(
        mul(scale(y, 2), path_denominator),
        scale(path_numerator, -1),
    )
    increasing = (
        derivative_numerator == {(0, 2): Q(1), (0, 1): Q(2)}
        and all(c > 0 for c in derivative_numerator.values())
    )

    # y^2/(1+y) tends to 0 at 0+ and to infinity at infinity.
    zero_limit = path_numerator.get((0, 0), Q(0))
    unbounded = (
        max(j for _, j in path_numerator)
        > max(j for _, j in path_denominator)
    )

    if not (identity_verified and increasing and zero_limit == 0 and unbounded):
        print(json.dumps({"final_answer": "UNSUPPORTED"}))
        return

    print(json.dumps({
        "final_answer": f"({boundary}, infinity)",
        "evidence": {
            "normalization": "x=a/c>0, t=sqrt(1+b/c)>1",
            "verified_identity":
                f"F-{boundary}=(x-t)^2/(x*t^2)+(t-1)^2*(t+2)/t>0",
            "surjective_path":
                f"a=c, y=b/c>0: F={boundary}+y^2/(1+y)",
            "path_derivative": "y*(y+2)/(1+y)^2>0",
            "path_limits": [str(boundary), "infinity"],
            "endpoint_attained": False
        }
    }, separators=(",", ":")))

main()
