one = {(0, 0): 1}
x = {(1, 0): 1}
t = {(0, 1): 1}
x2 = mul(x, x)
t2 = mul(t, t)
t4 = mul(t2, t2)

# Normalize x=a/c>0, y=b/c>0, and t=sqrt(1+y)>1.
# F = 1/x + x/t^2 + t^2 - 1.
# Verify the numerator of the exact identity
# F-2 = (x-t)^2/(x*t^2) + (t-1)^2*(t+2)/t.
lhs = add(t2, x2, mul(x, t4), scale(mul(x, t2), -3))
xm_t = add(x, scale(t, -1))
tm_1 = add(t, scale(one, -1))
rhs = add(
    mul(xm_t, xm_t),
    mul(mul(x, t), mul(mul(tm_1, tm_1), add(t, scale(one, 2))))
)
if lhs != rhs:
    print("UNSUPPORTED: algebraic certificate failed")
    print("CHECK UNKNOWN")
else:
    print("Exact identity verified:")
    print("F-2 = (x-t)^2/(x*t^2) + (t-1)^2*(t+2)/t.")
    print("Since x>0 and t>1, the second term is strictly positive.")
