    discriminant = {(2, 0): 1, (1, 0): 4}  # k^2+4k
    residual = add(discriminant, {(2, 0): -1, (1, 0): -4})
    assert residual == {}
    print("Every target 2+k (k>0) is attained by:")
    print("a=c=1, b=(k+sqrt(k^2+4*k))/2.")
    print("The defining quadratic is verified exactly.")

