from itertools import permutations
from math import comb

# Exact polynomials in x, s = sin(theta), c = cos(theta).
def add(a, b):
    result = a.copy()
    for powers, coefficient in b.items():
        result[powers] = result.get(powers, 0) + coefficient
    return {p: v for p, v in result.items() if v}

def multiply(a, b):
    result = {}
    for p, u in a.items():
        for q, v in b.items():
            powers = tuple(i + j for i, j in zip(p, q))
            result[powers] = result.get(powers, 0) + u * v
    return {p: v for p, v in result.items() if v}

def determinant(matrix):
    result = {}
    for permutation in permutations(range(3)):
        inversions = sum(
            permutation[i] > permutation[j]
            for i in range(3) for j in range(i + 1, 3)
        )
        term = {(0, 0, 0): (-1) ** inversions}
        for row, column in enumerate(permutation):
            term = multiply(term, matrix[row][column])
        result = add(result, term)
    return result

x = {(1, 0, 0): 1}
s = {(0, 1, 0): 1}
c = {(0, 0, 1): 1}
one = {(0, 0, 0): 1}
negative_x = {(1, 0, 0): -1}
negative_s = {(0, 1, 0): -1}

matrix = [
    [x, s, c],
    [negative_s, negative_x, one],
    [c, one, x],
]
expanded = determinant(matrix)

# Substitute c^2 = 1 - s^2 exactly, using the binomial theorem.
reduced = {}
for (px, ps, pc), coefficient in expanded.items():
    pairs, remainder = divmod(pc, 2)
    for k in range(pairs + 1):
        reduced = add(reduced, {
            (px, ps + 2 * k, remainder):
                coefficient * comb(pairs, k) * (-1) ** k
        })

print("Expanded determinant (powers of x, sin(theta), cos(theta)):", expanded)
print("After sin(theta)^2 + cos(theta)^2 = 1:", reduced)
if reduced == {(3, 0, 0): -1}:
    print("Expected result: -x^3")

# Exact admissible counterexample: x = 1, theta = 0.
value = sum(
    coefficient * 1 ** px * 0 ** ps * 1 ** pc
    for (px, ps, pc), coefficient in expanded.items()
)
print("At x = 1, theta = 0: determinant =", value)
print("Submitted answer: 0")
print("CHECK FAIL" if value != 0 else
      "CHECK PASS" if not reduced else "CHECK UNKNOWN")
