import json
from fractions import Fraction
from math import comb

def add(a, b):
    out = dict(a)
    for power, coefficient in b.items():
        out[power] = out.get(power, Fraction(0)) + coefficient
    return {p: c for p, c in out.items() if c}

def multiply(a, b):
    out = {}
    for p, c in a.items():
        for q, d in b.items():
            out[p + q] = out.get(p + q, Fraction(0)) + c * d
    return {p: c for p, c in out.items() if c}

def encode(poly):
    return {str(p): str(poly[p]) for p in sorted(poly)}

# Put s = sin(x), c = cos(x).
# Angle subtraction/addition gives:
# sin(60°-x) sin(60°+x) = sin²(60°) c² - cos²(60°) s².
# An equilateral triangle gives cos(60°) = 1/2 exactly.
cos60 = Fraction(1, 2)
cos60_squared = cos60 * cos60
sin60_squared = 1 - cos60_squared

# Substitute c² = 1 - s² and multiply by 4s.
pair = add(
    {0: sin60_squared, 2: -sin60_squared},
    {2: -cos60_squared},
)
original = multiply({1: Fraction(4)}, pair)

def odd_sine_multiple(n):
    # Expand Im((c + i*s)**n), using c² = 1 - s².
    # The angle-addition formulas establish that this is sin(n*x).
    poly = {}
    for k in range(1, n + 1, 2):
        factor = Fraction(comb(n, k) * (-1) ** ((k - 1) // 2))
        exponent = (n - k) // 2
        for j in range(exponent + 1):
            power = k + 2 * j
            coefficient = factor * comb(exponent, j) * (-1) ** j
            poly[power] = poly.get(power, Fraction(0)) + coefficient
    return {p: c for p, c in poly.items() if c}

matches = [
    n for n in range(1, 10, 2)
    if odd_sine_multiple(n) == original
]

if len(matches) != 1:
    print("UNSUPPORTED")
else:
    n = matches[0]
    print(json.dumps({
        "final_answer": f"sin({n}x)",
        "evidence": {
            "variable": "s = sin(x); angles in degrees",
            "sin_squared_60": str(sin60_squared),
            "original_polynomial": encode(original),
            "matched_multiple": n,
            "independently_expanded_polynomial": encode(odd_sine_multiple(n)),
            "domain": "all real x"
        }
    }, separators=(",", ":")))
