from fractions import Fraction
from math import comb

# Exact polynomials in the formal variables n and x.
# Keys (a, b) represent n**a * x**b.
def clean(p):
    return {term: coefficient for term, coefficient in p.items() if coefficient}

def add(*polys):
    result = {}
    for p in polys:
        for term, coefficient in p.items():
            result[term] = result.get(term, Fraction(0)) + coefficient
    return clean(result)

def scale(p, c):
    return clean({term: c * coefficient for term, coefficient in p.items()})

def mul(p, q):
    result = {}
    for (a, b), c in p.items():
        for (d, e), f in q.items():
            term = (a + d, b + e)
            result[term] = result.get(term, Fraction(0)) + c * f
    return clean(result)

def at_n_plus_one(p):
    result = {}
    for (a, b), c in p.items():
        for j in range(a + 1):
            term = (j, b)
            result[term] = result.get(term, Fraction(0)) + c * comb(a, j)
    return clean(result)

def evaluate(p, n, x):
    return sum((c * n**a * x**b for (a, b), c in p.items()), Fraction(0))

one = {(0, 0): Fraction(1)}
n = {(1, 0): Fraction(1)}
x = {(0, 1): Fraction(1)}
x2 = mul(x, x)
n2 = mul(n, n)

# Binomial weights obey
# w_(n+1,k) = (1-x) w_(n,k) + x w_(n,k-1).
# Thus their total mass S and first two raw moments obey:
# S' = S, M1' = M1 + x*S, M2' = M2 + 2*x*M1 + x*S.
# These identities follow by reindexing finite sums, including endpoints.
S = one
M1 = mul(n, x)
M2 = add(mul(mul(n, add(n, scale(one, -1))), x2), mul(n, x))

checks = [
    evaluate(S, 0, Fraction(1, 3)) == 1,
    clean({term: c for term, c in M1.items() if term[0] == 0}) == {},
    clean({term: c for term, c in M2.items() if term[0] == 0}) == {},
    at_n_plus_one(S) == S,
    at_n_plus_one(M1) == add(M1, mul(x, S)),
    at_n_plus_one(M2) == add(M2, scale(mul(x, M1), 2), mul(x, S)),
]

# Since p_n(x) = M2/n^2 for f(t)=t^2, verify the exact
# numerator identity before dividing by n>0.
target = add(x, scale(x2, -1))
checks.append(
    add(M2, scale(mul(n2, x2), -1)) == mul(n, target)
)
checks.extend([
    evaluate(target, 1, Fraction(0)) == 0,
    evaluate(target, 1, Fraction(1)) == 0,
])

if all(checks):
    print("Exact symbolic induction verifies the binomial moments for every n >= 0.")
    print("p_n(x) = x^2 + x(1-x)/n for every integer n >= 1.")
    print("Therefore n*(p_n(x)-x^2) = x(1-x) exactly, not just in the limit.")
    print("Boundary values: x=0 -> 0; x=1 -> 0.")
    print("The claimed limit holds for every x in [0,1].")
    print("CHECK PASS")
else:
    print("Exact identity checks:", checks)
    print("UNSUPPORTED: the symbolic verification did not complete successfully.")
    print("CHECK UNKNOWN")
