    print("UNSUPPORTED")
else:
    upper = positive_branch
    lower = upper.copy()
    lower[0] -= 1

    def evaluate(coefficients, k):
        return sum(c * k**i for i, c in enumerate(coefficients))

    answer = (
        "Union over integers k >= 0 of "
        f"({polynomial(lower, 'k')}, {polynomial(upper, 'k')}]."
