import json
from collections import Counter

def evaluate(p, x):
    value = 0
    for coefficient in reversed(p):
        value = value * x + coefficient
    return value

def divide_by_root(p, root):
    quotient = [0] * (len(p) - 1)
    quotient[-1] = p[-1]
    for i in range(len(quotient) - 2, -1, -1):
        quotient[i] = p[i + 1] + root * quotient[i + 1]
    assert p[0] + root * quotient[0] == 0
    return quotient

def factor_monic(p):
    remainder = p[:]
    factors = []
    while len(remainder) > 1 and remainder[0] != 0:
        constant = abs(remainder[0])
        candidates = [
            sign * d
            for d in range(1, constant + 1)
            if constant % d == 0
            for sign in (1, -1)
        ]
        root = next(
            (r for r in candidates if evaluate(remainder, r) == 0),
            None
        )
        if root is None:
            break
        factors.append([-root, 1])
        remainder = divide_by_root(remainder, root)
    if len(remainder) > 1:
        factors.append(remainder)
    else:
        assert remainder == [1]
    return factors

def multiply(p, q):
    result = [0] * (len(p) + len(q) - 1)
    for i, a in enumerate(p):
        for j, b in enumerate(q):
            result[i + j] += a * b
    return result

def reconstruct(factors):
    result = [1]
    for factor in factors:
        result = multiply(result, factor)
    return result

def power(variable, exponent):
    if exponent == 0:
        return ""
    return variable if exponent == 1 else variable + "^" + str(exponent)

def homogeneous_text(p, x, y):
    degree = len(p) - 1
    terms = []
    for i in range(degree, -1, -1):
        coefficient = p[i]
        if coefficient == 0:
            continue
        variables = "*".join(
            v for v in (power(x, i), power(y, degree - i)) if v
        )
        magnitude = abs(coefficient)
        body = variables if magnitude == 1 and variables else str(magnitude)
        if magnitude != 1 and variables:
            body += "*" + variables
        if not terms:
            terms.append(("-" if coefficient < 0 else "") + body)
        else:
            terms.append((" - " if coefficient < 0 else " + ") + body)
    return "".join(terms)

def factor_text(factors, x, y):
    counts = Counter(tuple(factor) for factor in factors)
    pieces = []
    for factor, multiplicity in counts.items():
        piece = "(" + homogeneous_text(factor, x, y) + ")"
        if multiplicity > 1:
            piece += "^" + str(multiplicity)
        pieces.append(piece)
    return "*".join(pieces)

originals = [[-1, 0, 0, 0, 1], [1, -2, 1]]
factorizations = [factor_monic(p) for p in originals]
checks = [reconstruct(factors) for factors in factorizations]

if checks != originals:
    print("UNSUPPORTED")
else:
    answers = [
        factor_text(factorizations[0], "a", "b"),
        factor_text(factorizations[1], "sqrt(a)", "sqrt(b)")
    ]
    print(json.dumps({
        "final_answer": (
            "a^4 - b^4 = " + answers[0] + "; "
            "a + b - 2*sqrt(a*b) = " + answers[1]
        ),
        "evidence": {
            "verified_coefficients_ascending": checks,
            "homogenization": [
                "b^4*((a/b)^4 - 1)",
