    ("gjiansale’wit", "əkciansalēwit"),
    ("mgumie’jo’tlatl", "əmkumiējōdəladəl"),
    ("amqwanji’j", "amxʷancīc"),
    ("e’jnt", "ējənt"),
    ("tplutaqan", "ətpəludaɣan"),
    ("ge’gwising", "gēgʷisink"),
    ("lnu’sgw", "lənūskw"),
    ("g’p’ta’q", "gəbədāx"),
    ("epsaqtejg", "epsaxteck"),
]

def vowel(token):
    return token[0] in "aeiouə"

def transcribe(word):
    tokens = []
    for ch in word:
        if ch in "'’":
            if not tokens:
                raise ValueError("Unattached apostrophe")
            if vowel(tokens[-1]):
                tokens[-1] += "\u0304"
            else:
                tokens.append("ə")
        else:
            tokens.append(ch)

    # Break clusters before m, n, or l with schwa.
    expanded = []
    for token in tokens:
        if (expanded and token in "mnl"
                and not vowel(expanded[-1])):
            expanded.append("ə")
        expanded.append(token)

    # Remaining initial consonant clusters take a preceding schwa.
    if (len(expanded) >= 2 and not vowel(expanded[0])
            and not vowel(expanded[1])):
        expanded.insert(0, "ə")

    output = []
    i = 0
    while i < len(expanded):
        token = expanded[i]
        left_vowel = i == 0 or vowel(expanded[i - 1])
        right_vowel = (
            i + 1 < len(expanded) and vowel(expanded[i + 1])
        )

        if token == "q" and i + 1 < len(expanded) and expanded[i + 1] == "w":
            output.append("ɣʷ" if left_vowel else "xʷ")
            i += 2
            continue

        if (token == "g" and i + 2 < len(expanded)
                and expanded[i + 1] == "w"
                and vowel(expanded[i + 2])):
            output.append("gʷ" if left_vowel else "kʷ")
            i += 2
            continue

        if token in "tgjq":
            voiced, voiceless = {
                "t": ("d", "t"),
                "g": ("g", "k"),
                "j": ("j", "c"),
                "q": ("ɣ", "x"),
            }[token]
            output.append(
                voiced if left_vowel and right_vowel else voiceless
            )
        else:
            output.append(token)
        i += 1

    return "".join(output), "".join(expanded)

checks = [transcribe(word)[0] == expected for word, expected in data]
if not all(checks):
    print(json.dumps({
        "final_answer": "UNSUPPORTED",
        "evidence": {"matched_examples": sum(checks), "total": len(data)}
    }, ensure_ascii=False))
else:
    answer, intermediate = transcribe("gmu’jmin")
