import unicodedata

# Rules needed for this word:
#   vowel + ’ -> long vowel
#   consonant + ’ -> schwa
#   a consonant followed by m/n/l acquires intervening schwa
#   t/p are voiced before a vowel when word-initial or after a vowel
#   j between vowels is [j], rather than voiceless [c]
#
# Validate the relevant rules against supplied examples before using them.

VOWELS = set("aeiou")
SONORANTS = set("mnl")
LONG = {v: v + "\u0304" for v in VOWELS}

def vowel(token):
    return token[0] in VOWELS or token == "ə"

def transcribe_relevant(word):
    tokens = []
    for ch in word:
        if ch in ("’", "'"):
            assert tokens
            if tokens[-1] in VOWELS:
                tokens[-1] = LONG[tokens[-1]]
            else:
                tokens.append("ə")
        else:
            tokens.append(ch)

    expanded = []
    for i, token in enumerate(tokens):
        expanded.append(token)
        if (i + 1 < len(tokens)
                and not vowel(token)
                and tokens[i + 1] in SONORANTS):
            expanded.append("ə")

    result = []
    for i, token in enumerate(expanded):
        left = expanded[i - 1] if i else None
        right = expanded[i + 1] if i + 1 < len(expanded) else None
        if token in ("t", "p"):
            if right is not None and vowel(right) and (
                    left is None or vowel(left)):
                token = {"t": "d", "p": "b"}[token]
        elif token == "j":
            token = "j" if (
                left is not None and right is not None
                and vowel(left) and vowel(right)
            ) else "c"
        elif token == "q":
            token = "x"
        result.append(token)
    return "".join(result)

def normalize_ipa(s):
    s = s.strip("[]")
    s = unicodedata.normalize("NFD", s)
    # Treat macron and IPA length mark as equivalent length notation.
    return s.replace("\u0304", "ː")

witnesses = [
    ("tmi’gn", "dəmīgən"),
    ("e’jnt", "ējənt"),
    ("g’p’ta’q", "gəbədāx"),
]
for spelling, supplied in witnesses:
    computed = transcribe_relevant(spelling)
    assert normalize_ipa(computed) == normalize_ipa(supplied), (
        spelling, computed, supplied
    )

expected = transcribe_relevant("gmu’jmin")
submitted = "[gmuːcmɪn]"

print("Relevant supplied examples verified:", len(witnesses))
print("Expected: [" + expected + "]")
print("Submitted:", submitted)
print("Length-notation differences are ignored in comparison.")
if normalize_ipa(expected) == normalize_ipa(submitted):
    print("CHECK PASS")
else:
    print("Differences: missing schwas, c instead of j, and ɪ instead of i.")
    print("CHECK FAIL")
