import json
from math import gcd, isqrt

def prime(n):
    if n < 2:
        return False
    return all(n % d != 0 for d in range(2, isqrt(n) + 1))

def colon(a, b):
    return (a + a) * b if b < 2 else (b + b) * a

def cross(a, b):
    return a * b if colon(a, b) > 0 else (-a) * (-b)

def tilde(a, b):
    g = gcd(a, b)
    return a - b if g == 1 else g

def bang(a, b):
    return min(a, b) if prime(a) or prime(b) else max(a, b)

def hash_op(a, b):
    return a - b if tilde(a, b) > 0 else colon(a, b)

operations = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    ":": colon,
    "><": cross,
    "~": tilde,
    "!": bang,
    "#": hash_op,
}

def chain(start, steps):
    values = [start]
    for op, operand in steps:
        values.append(operations[op](values[-1], operand))
    return values[-1], values

a_left = tilde(
    bang(4 + 4, hash_op(7, 8)),
    bang(5, 4) * colon(-7, -6),
)
a_right = hash_op(
