def exact_sqrt(x):
    if x < 0:
        return None
    n = isqrt(x.numerator)
    d = isqrt(x.denominator)
    if n * n == x.numerator and d * d == x.denominator:
        return Fraction(n, d)
    return None

witnesses = []
for a in map(Fraction, (-1, 0, 1)):
    for b in map(Fraction, (-1, 0, 1)):
        sa = exact_sqrt(1 - a * a)
        sb = exact_sqrt(1 - b * b)
        if sa is not None and sb is not None:
            lhs = a * sb - b * sa
            if lhs == 1:
                witnesses.append({
                    "a": str(a),
                    "b": str(b),
                    "original_lhs": str(lhs),
                    "D": str(a * a - b * b),
                })

values = {w["D"] for w in witnesses}
answer = "D is not uniquely determined." if len(values) > 1 else "UNSUPPORTED"
print(json.dumps({"final_answer": answer, "evidence": witnesses},
