import json
from fractions import Fraction

# Generic coordinates: H=(0,0), A=(-a,0), B=(0,b), C=(c,0),
# where a,b,c>0. These cover the given configuration after a rigid motion.
# Polynomials in a,b,c are stored as exponent-tuples -> exact coefficients.

ZERO = {}
ONE = {(0, 0, 0): Fraction(1)}

def variable(i):
    powers = [0, 0, 0]
    powers[i] = 1
    return {tuple(powers): Fraction(1)}

def add(p, q):
    result = dict(p)
    for powers, coefficient in q.items():
        result[powers] = result.get(powers, Fraction(0)) + coefficient
        if result[powers] == 0:
            del result[powers]
    return result

def scale(p, factor):
    factor = Fraction(factor)
    return {powers: coefficient * factor
            for powers, coefficient in p.items()
            if coefficient * factor != 0}

def subtract(p, q):
    return add(p, scale(q, -1))

def multiply(p, q):
    result = {}
    for u, x in p.items():
        for v, y in q.items():
            powers = tuple(u[i] + v[i] for i in range(3))
            result[powers] = result.get(powers, Fraction(0)) + x * y
    return {powers: coefficient for powers, coefficient in result.items()
            if coefficient != 0}

def midpoint(P, Q):
    return tuple(scale(add(p, q), Fraction(1, 2))
                 for p, q in zip(P, Q))

def signed_double_area(P, Q, R):
    ux, uy = (subtract(q, p) for p, q in zip(P, Q))
    vx, vy = (subtract(r, p) for p, r in zip(P, R))
    return subtract(multiply(ux, vy), multiply(uy, vx))

def serialize(poly):
    return [
        {"powers_of_a_b_c": list(powers), "coefficient": str(coefficient)}
        for powers, coefficient in sorted(poly.items())
    ]

a, b, c = (variable(i) for i in range(3))
H = (ZERO, ZERO)
A = (scale(a, -1), ZERO)
B = (ZERO, b)
C = (c, ZERO)

# ABH is right at H because BH perpendicular AC.
# BHD and HDC are right at D because HD perpendicular BC.
# A right triangle's circumcenter is its hypotenuse midpoint.
O1 = midpoint(A, B)
O2 = midpoint(B, H)
O3 = midpoint(H, C)

numerator = signed_double_area(O1, O2, O3)
denominator = signed_double_area(A, B, H)

if not denominator:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}}))
else:
    term = next(iter(denominator))
    signed_ratio = numerator.get(term, Fraction(0)) / denominator[term]
    if numerator != scale(denominator, signed_ratio):
        print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}}))
    else:
        print(json.dumps({
            "final_answer": str(abs(signed_ratio)),
            "evidence": {
                "parameters": "a,b,c>0",
                "circumcenters": [
                    "midpoint(A,B)",
                    "midpoint(B,H)",
                    "midpoint(H,C)"
                ],
                "signed_double_area_O1O2O3": serialize(numerator),
                "signed_double_area_ABH": serialize(denominator),
                "exact_polynomial_proportionality_verified": True
            }
        }, separators=(",", ":")))
