import json
import math

def is_prime(n):
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    for d in range(3, math.isqrt(n) + 1, 2):
        if n % d == 0:
            return False
    return True

def apply(a, op, b):
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op in ("&", "@"):
        return a - b if a * b > 0 else a + b
    if op == "!":
        return min(a, b) if is_prime(a) or is_prime(b) else max(a, b)
    if op == "#":
        g = math.gcd(a, b)
        return apply(a, "@", b) if g == 1 else g
    raise ValueError("Unknown operator")

