import json
from fractions import Fraction
from math import isqrt

def exact_sqrt(value):
    numerator = isqrt(value.numerator)
    denominator = isqrt(value.denominator)
    if numerator * numerator != value.numerator:
        return None
    if denominator * denominator != value.denominator:
        return None
    return Fraction(numerator, denominator)

def solve():
    # The sum is the right-endpoint Riemann sum on [0, 1].
    # First term: t = 1 + x, so dx = dt.
    first_offset = Fraction(1)
    first_slope = Fraction(1)
    first_bounds = (first_offset, first_offset + first_slope)
    first_weight = 1 / first_slope

    # Second term: t = sqrt(1 + 3x).
    # dx = (2t/3) dt, cancelling the denominator t.
    second_offset = Fraction(1)
    second_slope = Fraction(3)
    second_coefficient = Fraction(3, 2)

    if min(second_offset, second_offset + second_slope) <= 0:
        return {"final_answer": "UNSUPPORTED"}

    second_bounds = (
        exact_sqrt(second_offset),
        exact_sqrt(second_offset + second_slope),
    )
    if None in second_bounds:
        return {"final_answer": "UNSUPPORTED"}

    second_weight = -second_coefficient * 2 / second_slope

    # Both transformed integrands are exp(t^2). Combine exact weights
    # only when their integration bounds agree.
    integrals = {}
    for bounds, weight in (
        (first_bounds, first_weight),
        (second_bounds, second_weight),
    ):
        integrals[bounds] = integrals.get(bounds, Fraction(0)) + weight

    if any(weight != 0 for weight in integrals.values()):
        return {"final_answer": "UNSUPPORTED"}

    result = sum(integrals.values(), Fraction(0))
    return {
        "final_answer": str(result),
        "evidence": {
            "limit_rule": "Continuous integrands: right-endpoint Riemann sums converge to the integral on [0,1].",
            "substitutions": ["t=1+x", "t=sqrt(1+3x)"],
            "transformed_integrand": "exp(t^2)",
            "bounds": [
                [str(v) for v in first_bounds],
                [str(v) for v in second_bounds],
            ],
            "signed_weights": [str(first_weight), str(second_weight)],
            "combined_weight": str(result),
        },
    }

print(json.dumps(solve(), separators=(",", ":")))
