    "The capital of Afghanistan is Kandahar.": False,
    "The capital of the Nigeria is Abuja.": True,
    "The capital of UAE is Abu Dhabi.": True,
    "The capital of Canada is Toronto.": False,      # Ottawa
}

arithmetic = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}
comparisons = {
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
}


def compute(node):
    """Evaluate only the required syntax, with exact rational arithmetic."""
    if isinstance(node, ast.Expression):
        return compute(node.body)

    if isinstance(node, ast.Constant):
        if type(node.value) is bool:
            return node.value
        if type(node.value) is int:
            return Fraction(node.value)
        raise ValueError("Unexpected constant")

    if isinstance(node, ast.UnaryOp):
        value = compute(node.operand)
        if isinstance(node.op, ast.Not):
            return not value
        if isinstance(node.op, ast.USub):
            return -value
        if isinstance(node.op, ast.UAdd):
            return value
        raise ValueError("Unexpected unary operator")

    if isinstance(node, ast.BinOp):
        return arithmetic[type(node.op)](
            compute(node.left), compute(node.right)
        )

    if isinstance(node, ast.BoolOp):
        values = [compute(v) for v in node.values]
        if not all(type(v) is bool for v in values):
            raise ValueError("Non-Boolean logical operand")
        if isinstance(node.op, ast.And):
            return all(values)
        if isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError("Unexpected logical operator")

    if isinstance(node, ast.Compare):
        left = compute(node.left)
        outcomes = []
        for op, right_node in zip(node.ops, node.comparators):
            right = compute(right_node)
            outcomes.append(comparisons[type(op)](left, right))
            left = right
        return all(outcomes)

    if isinstance(node, ast.Call):
        if (not isinstance(node.func, ast.Name)
                or node.func.id not in ("max", "min")
                or node.keywords):
            raise ValueError("Unexpected function call")
        function = max if node.func.id == "max" else min
        return function(compute(arg) for arg in node.args)

    raise ValueError("Unexpected syntax: " + type(node).__name__)


results = {}
try:
    for label, source in expressions.items():
        for statement, truth in facts.items():
            source = source.replace(statement, str(truth))
        source = source.replace("is less than or equal to", "<=")
        source = source.replace("is greater than", ">")
        value = compute(ast.parse(source, mode="eval"))
        if type(value) is not bool:
            raise ValueError("Option did not evaluate to a Boolean")
        results[label] = value
except (SyntaxError, ValueError, KeyError, TypeError, ZeroDivisionError) as exc:
    print("UNSUPPORTED:", exc)
    print("CHECK UNKNOWN")
else:
    for label, value in results.items():
        print(f"({label}) = {value}")
    true_options = [label for label, value in results.items() if value]
    print("True options:", ", ".join(true_options) or "none")
    print("Submitted answer: (B)")
    print("CHECK PASS" if true_options == ["B"] else "CHECK FAIL")
