from fractions import Fraction

# Polynomials in (h, f1, f2), represented exactly by exponent dictionaries.
ZERO = (0, 0, 0)

def clean(p):
    return {m: c for m, c in p.items() if c}

def add(p, q):
    result = dict(p)
    for m, c in q.items():
        result[m] = result.get(m, Fraction(0)) + c
    return clean(result)

def multiply(p, q):
    result = {}
    for a, ca in p.items():
        for b, cb in q.items():
            m = tuple(x + y for x, y in zip(a, b))
            result[m] = result.get(m, Fraction(0)) + ca * cb
    return clean(result)

variables = {
    "h": {(1, 0, 0): Fraction(1)},
    "f1": {(0, 1, 0): Fraction(1)},
    "f2": {(0, 0, 1): Fraction(1)},
}

def certify(expr):
    """Compute a polynomial and derive continuity using all antecedents."""
    if isinstance(expr, int):
        return {ZERO: Fraction(expr)}, True
    if isinstance(expr, str):
        # h is continuous by complete separation; f1 and f2 by hypothesis.
        return variables[expr], True
    operation, left, right = expr
    p, left_continuous = certify(left)
    q, right_continuous = certify(right)
    if operation == "+":
        result = add(p, q)
    elif operation == "*":
        result = multiply(p, q)
    else:
        raise ValueError("Unrecognized operation")
    return result, left_continuous and right_continuous

def substitute_h(p, value):
    result = {}
    for (h_power, u_power, v_power), coefficient in p.items():
        m = (0, u_power, v_power)
        result[m] = (
            result.get(m, Fraction(0))
            + coefficient * Fraction(value) ** h_power
        )
    return clean(result)

# Complete separation supplies continuous h:X->[0,1], h|A=0, h|B=1.
expression = (
    "+",
    ("*", ("+", 1, ("*", -1, "h")), "f1"),
    ("*", "h", "f2"),
)
g, continuous = certify(expression)

on_A = substitute_h(g, 0) == variables["f1"]
on_B = substitute_h(g, 1) == variables["f2"]
expected_yes = continuous and on_A and on_B
submitted_yes = True

print("Complete separation supplies continuous h with h|A=0 and h|B=1.")
print("Construction: g = (1-h)*f1 + h*f2.")
print("Continuity derived from sums and products:", continuous)
print("Exact symbolic identity g|A = f1:", on_A)
print("Exact symbolic identity g|B = f2:", on_B)
print("These are universal polynomial identities, not sampled tests.")
print("Expected answer:", "yes" if expected_yes else "not established")
print("CHECK PASS" if expected_yes and submitted_yes else "CHECK FAIL")
