import itertools
import json
from math import gcd
from functools import reduce

def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def cross(a, b):
    return (a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0])

def canonical(v):
    g = reduce(gcd, (abs(x) for x in v), 0)
    if not g:
        return None
    v = tuple(x // g for x in v)
    return tuple(-x for x in v) if next(x for x in v if x) < 0 else v

directions = sorted({
    canonical(v)
    for v in itertools.product((-1, 0, 1), repeat=3)
    if any(v)
})

def counterexample(label):
    for a, b, g in itertools.permutations(directions, 3):
        if label == "A":
            if dot(a, b) != 0:
                continue
            ell = canonical(cross(a, b))
            candidates = [
                m for m in directions
                if dot(m, ell) == 0 and cross(m, b) != (0, 0, 0)
            ]
        elif label == "B":
            if dot(a, g) != 0 or dot(b, g) != 0:
                continue
            candidates = [canonical(cross(a, g))]
            ell = None
        else:
            if dot(a, g) != 0 or dot(b, g) != 0:
                continue
            candidates = [a]
            ell = None

        for m in candidates:
            if m is None or cross(m, b) == (0, 0, 0):
                continue
            l = ell or next(v for v in directions if v != m)
            if l == m:
                continue
            n = next(v for v in directions if v not in (m, l))
            return {
                "plane_normals": {"alpha": a, "beta": b, "gamma": g},
                "line_directions": {"m": m, "n": n, "l": l},
                "m_cross_beta_normal": cross(m, b),
                "placement": "All planes and lines pass through the origin."
            }
    return None

# Sparse exact polynomials in x,y,z,s,r,q.
ZERO = (0,) * 6

def variable(i):
    exponent = list(ZERO)
    exponent[i] = 1
    return {tuple(exponent): 1}

def multiply(p, q):
    result = {}
    for e, c in p.items():
        for f, d in q.items():
            k = tuple(x + y for x, y in zip(e, f))
            result[k] = result.get(k, 0) + c*d
    return {k: v for k, v in result.items() if v}

def subtract(p, q):
    result = dict(p)
    for k, v in q.items():
        result[k] = result.get(k, 0) - v
    return {k: v for k, v in result.items() if v}

def polynomial_cross(u, v):
    return [
        subtract(multiply(u[i], v[j]), multiply(u[j], v[i]))
        for i, j in ((1, 2), (2, 0), (0, 1))
    ]

def solve():
    evidence = {}
    for label in ("A", "B", "C"):
        witness = counterexample(label)
        if witness is None:
            return None
        evidence[label] = witness

    # Under D, let a,b be plane normals and d the direction of n.
    # Perpendicularity gives a=s*d, b=r*d, with s,r nonzero.
    # Since m is perpendicular to alpha, its direction is q*a.
    d = [variable(i) for i in range(3)]
    s, r, q = (variable(i) for i in range(3, 6))
    a = [multiply(s, x) for x in d]
    b = [multiply(r, x) for x in d]
    m = [multiply(q, x) for x in a]
    residual = polynomial_cross(m, b)
    certified = all(not component for component in residual)
    if not certified:
        return None

    evidence["D"] = {
        "universal_parameterization":
