import json

def tile_square(n):
    full = (1 << (n * n)) - 1
    placements = []
    covering = [[] for _ in range(n * n)]

    # Every L triomino is a 2-by-2 block with one corner removed.
    for r in range(n - 1):
        for c in range(n - 1):
            block = [
                r * n + c, r * n + c + 1,
                (r + 1) * n + c, (r + 1) * n + c + 1
            ]
            for omitted in block:
                cells = tuple(x for x in block if x != omitted)
                mask = sum(1 << x for x in cells)
                index = len(placements)
                placements.append((mask, cells))
                for x in cells:
                    covering[x].append(index)

    failed = set()

    def search(occupied):
        if occupied == full:
            return []
        if occupied in failed:
            return None

        best = None
        for cell in range(n * n):
            if occupied & (1 << cell):
                continue
            options = [
                i for i in covering[cell]
                if not (placements[i][0] & occupied)
            ]
            if not options:
                failed.add(occupied)
                return None
            if best is None or len(options) < len(best):
                best = options
                if len(best) == 1:
                    break

        for i in best:
            result = search(occupied | placements[i][0])
            if result is not None:
                return [placements[i][1]] + result

        failed.add(occupied)
        return None

    return search(0)

n = 6
tiles = tile_square(n)

if tiles is None:
    print(json.dumps({"final_answer": "UNSUPPORTED"}))
else:
    board = [["." for _ in range(n)] for _ in range(n)]
    seen = set()
    for i, tile in enumerate(tiles):
        coordinates = [divmod(cell, n) for cell in tile]
        assert len(set(tile)) == 3
        assert max(r for r, c in coordinates) - min(r for r, c in coordinates) == 1
        assert max(c for r, c in coordinates) - min(c for r, c in coordinates) == 1
        for cell, (r, c) in zip(tile, coordinates):
            assert cell not in seen
            seen.add(cell)
            board[r][c] = chr(ord("A") + i)

    assert seen == set(range(n * n))
    print(json.dumps({
        "final_answer": (
            f"Yes. A {n}-by-{n} square can be formed using "
            f"{len(tiles)} three-cell L-shaped pieces."
        ),
        "evidence": {
            "tiling": ["".join(row) for row in board],
            "key": "Each letter denotes one L-shaped piece."
        }
    }, separators=(",", ":")))
