# Check both orientations of an 8-by-10 board, since nine upward
# steps require ten rows. Colors and unspecified endpoints are exhaustive.
for rows, columns in ((8, 10), (10, 8)):
    counts = set()
    aligned_counts = set()

    for white_parity in (0, 1):
        for p_column in range(columns):
            ways = [0] * columns
            ways[p_column] = 1

            for row in range(1, 10):
                next_ways = [0] * columns
                if row < rows:
                    for column, count in enumerate(ways):
                        for destination in range(
                            max(0, column - 1),
                            min(columns, column + 2)
                        ):
                            if (row + destination) % 2 == white_parity:
                                next_ways[destination] += count
                ways = next_ways

            # A nine-step path must finish on the top row.
            if rows - 1 != 9:
                ways = [0] * columns

            counts.update(ways)
            aligned_counts.add(ways[p_column])

