import json
from fractions import Fraction

def add(A, B):
    return tuple(tuple(a + b for a, b in zip(ra, rb))
                 for ra, rb in zip(A, B))

def mul(A, B):
    return tuple(
        tuple(sum(A[i][k] * B[k][j] for k in range(2))
              for j in range(2))
        for i in range(2)
    )

def norm(A):
    return max(sum(abs(a) for a in row) for row in A)

def matrix(A):
    return [[int(a) for a in row] for row in A]

F = Fraction
zero = ((F(0), F(0)), (F(0), F(0)))
x = ((F(1), F(0)), (F(0), F(1)))
y = ((F(-1), F(1)), (F(0), F(-1)))
s = add(x, y)

# These exact identities settle every positive integer power by induction.
settled = (
    s != zero
    and mul(s, s) == zero
    and mul(x, x) == x
    and norm(x) == 1
)

if settled:
    print(json.dumps({
        "final_answer": "No.",
        "evidence": {
            "space": "Real 2-by-2 matrices with the maximum absolute row-sum norm",
            "x": matrix(x),
            "y": matrix(y),
            "x_plus_y": matrix(s),
            "(x_plus_y)^2": matrix(mul(s, s)),
            "x^2": matrix(mul(x, x)),
            "justification": (
                "The sum is nonzero, but its square is zero, so all its "
                "powers from n=2 onward are zero and the stated limit is 0. "
                "Since x^2=x and ||x||=1, induction gives ||x^n||^(1/n)=1 "
                "for every positive integer n, so the second limit is 1."
            )
        }
    }, separators=(",", ":")))
else:
    print(json.dumps({"final_answer": "UNSUPPORTED", "evidence": {}}))
