    applicable = {
        i for i, (antecedents, _) in rules.items()
        if all(a in known for a in antecedents)
    }
    defeated = {
        i for i in applicable
        if any(
            (j, i) in preferred
            and rules[j][1] == opposite(rules[i][1])
            for j in applicable
        )
    }
    accepted = applicable - defeated
    return {rules[i][1] for i in accepted}, accepted, defeated

# Exhaustively check all possible sets of rule conclusions.
heads = sorted({head for _, head in rules.values()})
models = []
for bits in itertools.product((False, True), repeat=len(heads)):
    model = {head for head, present in zip(heads, bits) if present}
    consequences, accepted, defeated = evaluate(model)
    if consequences == model:
        models.append((model, accepted, defeated))

if len(models) != 1:
    print("UNSUPPORTED")
else:
    model, accepted, defeated = models[0]
    positive = "gadwall_wants_swan" in model
    negative = "-gadwall_wants_swan" in model
    answer = (
        "proved" if positive and not negative else
        "disproved" if negative and not positive else
        "unknown"
    )
    print(json.dumps({
        "final_answer": answer,
